# Options chain latency tiers (E*TRADE-realistic adaptive guardrails).
# GOOD / WARNING / CRITICAL thresholds: `ORB_0DTE_CHAIN_LATENCY_*_MS` in configs (defaults below).
def _orb_0dte_chain_latency_good_ms() -> float:
    return float(get_config_value("ORB_0DTE_CHAIN_LATENCY_GOOD_MS", 900))


def _orb_0dte_chain_latency_warning_ms() -> float:
    return float(get_config_value("ORB_0DTE_CHAIN_LATENCY_WARNING_MS", 1500))


def _orb_0dte_chain_latency_critical_ms() -> float:
    return float(get_config_value("ORB_0DTE_CHAIN_LATENCY_CRITICAL_MS", 2000))


def _option_chain_latency_status(avg_ms: float) -> str:
    """Map rolling average chain latency to telemetry status (good | warning | critical)."""
    if avg_ms <= _orb_0dte_chain_latency_good_ms():
        return "good"
    if avg_ms <= _orb_0dte_chain_latency_critical_ms():
        return "warning"
    return "critical"


def _safe_canonical_exit_reason(legacy_reason: Optional[str]) -> str:
    """Resolve exit reason to catalog id; never raises (Cloud Run / path variance safe)."""
    lr = str(legacy_reason or "").strip() or "unknown"
    try:
        from easy0DTE.modules.options_exit_reason_catalog import canonical_exit_reason

        return str(canonical_exit_reason(lr))
    except Exception:
        pass
    try:
        import importlib

        m = importlib.import_module("easy0DTE.modules.options_exit_reason_catalog")
        fn = getattr(m, "canonical_exit_reason", None)
        if callable(fn):
            return str(fn(lr))
    except Exception:
        pass
    return lr


def _so_etf_eod_close_window_pt() -> Tuple[time_class, time_class]:
    """ETF SO stealth/mock batch close window (PT). Single source: configs/ORBSO.env."""

    def _parse(raw: str, dh: int, dm: int, ds: int = 0) -> time_class:
        s = (raw or "").strip()
        if not s:
            return time_class(dh, dm, ds)
        parts = s.replace(":", " ").split()
        try:
            h = int(parts[0])
            m = int(parts[1]) if len(parts) > 1 else 0
            sec = int(parts[2]) if len(parts) > 2 else 0
            return time_class(h % 24, m % 60, sec % 60)
        except (ValueError, IndexError):
            return time_class(dh, dm, ds)

    start_s = str(get_config_value("SO_ETF_EOD_CLOSE_START_PT", "12:55") or "12:55")
    end_s = str(get_config_value("SO_ETF_EOD_CLOSE_END_PT", "12:56") or "12:56")
    return _parse(start_s, 12, 55, 0), _parse(end_s, 12, 56, 0)


