log = logging.getLogger("prime_trading_system_optimized")


def _log_so_pipeline_drop(stage: str, symbol: str, reason: str, detail: str = "") -> None:
    """Cloud Logging: grep `SO_PIPELINE` + symbol for collection→execution drops."""
    tail = f" | detail={detail}" if detail else ""
    sym = symbol or "?"
    log.info(f"SO_PIPELINE | stage={stage} | action=drop | symbol={sym} | reason={reason}{tail}")


def _log_so_pipeline_pass(stage: str, detail: str) -> None:
    log.info(f"SO_PIPELINE | stage={stage} | action=pass | {detail}")


def _so_pipeline_symbol_set(signals: Optional[List[Dict[str, Any]]]) -> Set[str]:
    """Uppercase symbols from SO signal dicts (for diff / summary lines)."""
    out: Set[str] = set()
    for s in signals or []:
        if not isinstance(s, dict):
            continue
        sym = (s.get("symbol") or "").strip().upper()
        if sym:
            out.add(sym)
    return out


def _log_so_pipeline_diff(
    stage: str,
    left_label: str,
    left_syms: Set[str],
    right_label: str,
    right_syms: Set[str],
    detail: str = "",
) -> None:
    """Log set difference between two symbol pools (grep SO_PIPELINE + symbol)."""
    only_left = sorted(left_syms - right_syms)
    only_right = sorted(right_syms - left_syms)
    tail = f" | detail={detail}" if detail else ""
    log.info(
        f"SO_PIPELINE | stage={stage} | action=diff | only_in_{left_label}="
        f"{','.join(only_left) if only_left else '-'} | only_in_{right_label}="
        f"{','.join(only_right) if only_right else '-'}{tail}"
    )


def _log_so_pipeline_rank_snapshot(stage: str, signals: Optional[List[Dict[str, Any]]]) -> None:
    """Ordered rank line with priority_score for post-mortem (Cloud Logging)."""
    if not signals:
        log.info(f"SO_PIPELINE | stage={stage} | action=rank_snapshot | count=0 | order=-")
        return
    parts: List[str] = []
    for i, s in enumerate(signals, 1):
        if not isinstance(s, dict):
            continue
        sym = (s.get("symbol") or "?").strip().upper()
        ps = s.get("priority_score")
        if ps is None:
            try:
                ps = float(s.get("confidence", 0) or 0)
            except (TypeError, ValueError):
                ps = 0.0
        else:
            try:
                ps = float(ps)
            except (TypeError, ValueError):
                ps = 0.0
        parts.append(f"{i}:{sym}:{ps:.4f}")
    log.info(
        f"SO_PIPELINE | stage={stage} | action=rank_snapshot | count={len(parts)} | order={' ; '.join(parts)}"
    )


def _log_so_pipeline_execution_footer(
    allowlist: Optional[FrozenSet[str]],
    executed: List[Dict[str, Any]],
    rejected: List[Dict[str, Any]],
) -> None:
    """One-line summary: allowlist symbols not filled — pair with per-symbol drop lines above."""
    ex = _so_pipeline_symbol_set(executed)
    rj = _so_pipeline_symbol_set(rejected)
    if allowlist is not None and len(allowlist) > 0:
        not_executed = sorted(allowlist - ex)
        log.info(
            f"SO_PIPELINE | stage=execution_summary | action=footer | allowlist_count={len(allowlist)} | "
            f"executed_count={len(ex)} | rejected_attempt_count={len(rj)} | "
            f"allowlist_not_executed={','.join(not_executed) if not_executed else '-'} | "
            f"rejected_symbols={','.join(sorted(rj)) if rj else '-'} | "
            f"hint=grep_SO_PIPELINE_symbol_or_stage"
        )
    else:
        log.info(
            f"SO_PIPELINE | stage=execution_summary | action=footer | allowlist_count=0 | "
            f"executed_count={len(ex)} | rejected_attempt_count={len(rj)} | "
            f"allowlist_not_executed=- | rejected_symbols={','.join(sorted(rj)) if rj else '-'} | "
            f"note=no_allowlist_or_empty"
        )


