    async def _refresh_adv_data_if_needed(self):
        """
        Refresh ADV data daily for Slip Guard (Rev 00046).
        
        Called once per day when date changes (before ORB capture).
        Fetches 90-day average volume for all symbols to enable
        position size capping at 1% ADV.
        """
        try:
            from .adv_data_manager import get_adv_manager
            
            adv_manager = get_adv_manager()
            
            # Check if Slip Guard is enabled
            if not adv_manager.enabled:
                log.debug("Slip Guard disabled - skipping ADV refresh")
                return
            
            # Check if data is fresh (<24 hours)
            if not adv_manager.is_data_stale(max_age_hours=24):
                age_hours = (datetime.utcnow() - adv_manager.last_refresh).total_seconds() / 3600 if adv_manager.last_refresh else 0  # Rev 00073: UTC consistency
                log.debug(f"ADV data is fresh ({age_hours:.1f}h old) - skipping refresh")
                return
            
            log.info("🛡️ SLIP GUARD: Refreshing ADV data for all symbols...")
            
            # Get symbols from symbol list
            symbols = self.symbol_list if hasattr(self, 'symbol_list') and self.symbol_list else []
            
            if not symbols:
                # Fallback: Load from core_list.csv
                import pandas as pd
                try:
                    df = pd.read_csv('data/watchlist/core_list.csv')
                    symbols = df['symbol'].tolist()
                    log.info(f"   Loaded {len(symbols)} symbols from core_list.csv")
                except Exception as e:
                    log.error(f"Failed to load symbols from core_list.csv: {e}")
                    return
            
            # Refresh ADV data (run in executor to avoid blocking event loop)
            await asyncio.get_event_loop().run_in_executor(
                None,
                adv_manager.refresh_adv_data,
                symbols
            )
            
            stats = adv_manager.get_stats()
            log.info(f"✅ SLIP GUARD: ADV refresh complete")
            log.info(f"   Symbols loaded: {stats['symbols_loaded']}")
            log.info(f"   ADV limit: {stats['adv_limit_pct']}% of ADV")
            
            if stats['data_age_hours']:
                log.info(f"   Data age: {stats['data_age_hours']:.1f} hours")
            
        except Exception as e:
            log.error(f"Error refreshing ADV data: {e}")
            log.warning("⚠️ Slip Guard will use cached ADV data (if available)")
    
    def _core_canonical_symbol(self, sym_u: str) -> Optional[str]:
        """Return watchlist casing for an uppercase ticker, or None if not in core_list."""
        if not sym_u:
            return None
        su = sym_u.strip().upper()
        for s in self.symbol_list or []:
            if (s or "").strip().upper() == su:
                return (s or "").strip()
        return None
    
    async def _resync_live_stealth_from_etrade_portfolio(self) -> None:
        """
        After Cloud Run restart, E*TRADE may still show open SO core longs while stealth
        active_positions is empty — same failure mode as Demo mock↔stealth split-brain.
        Re-add each broker-held core long to stealth when quotes exist.
        """
        try:
            if self.config.mode != SystemMode.LIVE_MODE or not self.stealth_trailing:
                return
            tm = getattr(self, "trade_manager", None)
            et = getattr(tm, "etrade_trading", None) if tm else None
            if not et or not getattr(et, "is_authenticated", lambda: False)():
                return
            portfolio = await asyncio.to_thread(et.get_portfolio)
            if not portfolio:
                return
            readded = 0
            for ep in portfolio:
                sym_u = (getattr(ep, "symbol", "") or "").strip().upper()
                canonical = self._core_canonical_symbol(sym_u)
                if not canonical:
                    continue
                qty = int(getattr(ep, "quantity", 0) or 0)
                if qty <= 0:
                    continue
                if any(
                    k == canonical or (k or "").upper() == sym_u
                    for k in self.stealth_trailing.active_positions.keys()
                ):
                    continue
                try:
                    from .prime_models import PrimePosition, SignalSide

                    total_cost = float(getattr(ep, "total_cost", 0.0) or 0.0)
                    mval = float(getattr(ep, "market_value", 0.0) or 0.0)
                    entry_price = (total_cost / qty) if qty and total_cost > 0 else ((mval / qty) if qty and mval else 0.0)
                    if entry_price <= 0:
                        entry_price = max(0.01, float(getattr(ep, "market_value", 0.0) or 0.01) / max(qty, 1))
                    current_price = (mval / qty) if qty and mval > 0 else entry_price
                    pid = (getattr(ep, "position_id", "") or "").strip() or f"LIVE_{canonical}_{int(time.time())}"
                    position = PrimePosition(
                        position_id=pid,
                        symbol=canonical,
                        side=SignalSide.LONG,
                        quantity=qty,
                        entry_price=entry_price,
                        current_price=current_price,
                        entry_time=datetime.utcnow(),
                        metadata={"is_so_trade": True, "rehydrated_from_broker": True},
                    )
                    if not self.data_manager:
                        log.warning(
                            "ORB_SO_ETF_LIVE_STEALTH_RESYNC | action=skip | symbol=%s | reason=no_data_manager",
                            canonical,
                        )
                        continue
                    quote = await self.data_manager.get_batch_quotes([canonical])
                    if not quote or canonical not in quote:
                        log.warning(
                            "ORB_SO_ETF_LIVE_STEALTH_RESYNC | action=skip | symbol=%s | reason=no_quotes",
                            canonical,
                        )
                        continue
                    market_data = {
                        "price": quote[canonical].get("last", quote[canonical].get("price", current_price)),
                        "atr": quote[canonical].get("last", current_price) * 0.02,
                        "volume_ratio": 1.0,
                    }
                    orb_data = None
                    if hasattr(self, "orb_strategy_manager") and self.orb_strategy_manager:
                        orb_data = self.orb_strategy_manager.orb_data.get(canonical)
                    market_data.update(
                        {
                            "rsi": 50.0,
                            "momentum": 0.0,
                            "volatility": 0.02,
                            "entry_bar_high": orb_data.orb_high if orb_data else entry_price * 1.02,
                            "entry_bar_low": orb_data.orb_low if orb_data else entry_price * 0.98,
                            "orb_range_pct": float(getattr(orb_data, "orb_range_pct", 0) or 0) if orb_data else 0.0,
                        }
                    )
                    ok = await self.stealth_trailing.add_position(position, market_data)
                    if ok:
                        readded += 1
                        log.info(
                            "ORB_SO_ETF_LIVE_STEALTH_RESYNC | action=rehydrated | symbol=%s | position_id=%s",
                            canonical,
                            pid,
                        )
                    else:
                        log.warning(
                            "ORB_SO_ETF_LIVE_STEALTH_RESYNC | action=add_failed | symbol=%s | position_id=%s",
                            canonical,
                            pid,
                        )
                except Exception as one_err:
                    log.warning(
                        "ORB_SO_ETF_LIVE_STEALTH_RESYNC | action=error | symbol=%s | err=%s",
                        canonical,
                        one_err,
                    )
            if readded:
                log.info(
                    "ORB_SO_ETF_LIVE_STEALTH_RESYNC | action=summary | rehydrated_count=%d",
                    readded,
                )
        except Exception as e:
            log.warning("ORB_SO_ETF_LIVE_STEALTH_RESYNC | action=aborted | err=%s", e)
    
